SELECT Имена_станций.NAME, Имена_ОЭС.abbr AS oesname, Имена_областей.abbr AS oblname, Имена_станций.ordnumb, Станции_89_2000.YEAR, Станции_89_2000.NUST, Станции_89_2000.E, Станции_89_2000.eotp, Станции_89_2000.eurt, Станции_89_2000.eust, Станции_89_2000.Q, Станции_89_2000.turt, Станции_89_2000.tust, Станции_89_2000.b, Станции_89_2000.gaz, Станции_89_2000.mazut, Станции_89_2000.torf, Станции_89_2000.slan, Станции_89_2000.gtt, Станции_89_2000.proch, Станции_89_2000.ugol, Станции_89_2000.don, Станции_89_2000.podm, Станции_89_2000.pech, [Доп_угли99-2000].int, [Доп_угли99-2000].vork, Станции_89_2000.arkt, Станции_89_2000.kuzn, Станции_89_2000.ural, [Доп_угли99-2000].sver, [Доп_угли99-2000].chel, [Доп_угли99-2000].kizel, Станции_89_2000.bashk, Станции_89_2000.ekib, Станции_89_2000.karag, Станции_89_2000.kan, [Доп_угли99-2000].nazar, [Доп_угли99-2000].ibor, [Доп_угли99-2000].berez, [Доп_угли99-2000].per, Станции_89_2000.irkut, [Доп_угли99-2000].azey, [Доп_угли99-2000].cher, Станции_89_2000.hak, Станции_89_2000.tuv, Станции_89_2000.bur, [Доп_угли99-2000].gusin, [Доп_угли99-2000].tugn, Станции_89_2000.chit, Станции_89_2000.ner, Станции_89_2000.raich, Станции_89_2000.urg, Станции_89_2000.prim, Станции_89_2000.luch, Станции_89_2000.mag, Станции_89_2000.sah, Станции_89_2000.qotr, Станции_89_2000.snk, Станции_89_2000.ewtp, Станции_89_2000.NT, Станции_89_2000.obor, Станции_89_2000.VED, Станции_89_2000.OBL, Станции_89_2000.DEP, Станции_89_2000.OES, Станции_89_2000.ER, Станции_89_2000.NUMB1120, IIf([ved]<3,1,2) AS вед, IIf([ved]=1 Or [ved]=4,1,IIf([ved]=2 Or [ved]=3,2,0)) AS кэстэц, Имена_станций.D, Имена_станций.R, IIf([ved]>0,1,0) AS [sum], Имена_станций.MAIN, IIf([ved]>0,0,1) AS sost, IIf([main]>0,1,0) AS [group]
FROM (((Станции_89_2000 INNER JOIN Имена_станций ON Станции_89_2000.NUMB1120=Имена_станций.NUMB) INNER JOIN Имена_ОЭС ON Станции_89_2000.OES=Имена_ОЭС.oes) INNER JOIN Имена_областей ON Станции_89_2000.OBL=Имена_областей.OBL) LEFT JOIN [Доп_угли99-2000] ON (Станции_89_2000.YEAR=[Доп_угли99-2000].YEAR) AND (Станции_89_2000.NUMB1120=[Доп_угли99-2000].NUMB1120);
